import{J as e,n as t,ot as n,q as r}from"./chunks/framework.CU_ytobU.js";var i=JSON.parse(`{"title":"Class: Kernel<Events>","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: Kernel<Events>"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/kernel/classes/Kernel"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/api/@jsprismarine/kernel/classes/Kernel"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/kernel/src"}},"headers":[],"relativePath":"api/@jsprismarine/kernel/classes/Kernel.md","filePath":"api/@jsprismarine/kernel/classes/Kernel.md","lastUpdated":1793391945000}`),a={name:`api/@jsprismarine/kernel/classes/Kernel.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/kernel</a> / Kernel</p><h1 id="class-kernel-events" tabindex="-1">Class: Kernel&lt;Events&gt; <a class="header-anchor" href="#class-kernel-events" aria-label="Permalink to “Class: Kernel&lt;Events&gt;”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L51" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:51</a></p><p>The module kernel. It owns lifecycle, a token-keyed service registry, and the event bus; everything else — worlds, sessions, commands, networking, the tick loop — is a module.</p><p>Lifecycle: construct the kernel once, <code>register()</code> modules, then drive it through <code>registerAll()</code>, <code>start()</code>, and <code>stop()</code>. <code>registerAll()</code> runs every module&#39;s <code>register()</code> phase exactly once and validates providers and the dependency graph; after it, <code>get()</code> resolves provided services. <code>start()</code> runs <code>registerAll()</code> first when it has not run, then runs the <code>start()</code> phases in dependency order. <code>stop()</code> runs <code>stop()</code> phases in reverse order, logging failures instead of throwing, and returns the kernel to the registered state, so the same kernel — and the services its modules constructed — can be started again. Event listeners a module attaches are detached when it stops; a module that must survive a restart attaches its listeners in <code>start()</code>, not <code>register()</code>.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h3><p><code>Events</code> <em>extends</em> <a href="./../#eventmap"><code>EventMap</code></a> = <a href="./../#eventmap"><code>EventMap</code></a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Kernel</strong>&lt;<code>Events</code>&gt;(<code>options?</code>): <code>Kernel</code>&lt;<code>Events</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L62" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:62</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#kerneloptions"><code>KernelOptions</code></a> = <code>{}</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Kernel</code>&lt;<code>Events</code>&gt;</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="events-1" tabindex="-1">events <a class="header-anchor" href="#events-1" aria-label="Permalink to “events”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>events</strong>(): <a href="./../#eventbus"><code>EventBus</code></a>&lt;<code>Events</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L68" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:68</a></p><p>The kernel-owned event bus, unscoped. Module code should use its context&#39;s scoped handle.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><a href="./../#eventbus"><code>EventBus</code></a>&lt;<code>Events</code>&gt;</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>&lt;<code>T</code>&gt;(<code>token</code>): <code>T</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L164" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:164</a></p><p>Resolves a service for the host or for tests. Module code should resolve through its context instead.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to “T”">​</a></h5><p><code>T</code></p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="token" tabindex="-1">token <a class="header-anchor" href="#token" aria-label="Permalink to “token”">​</a></h5><p><a href="./../#servicetoken"><code>ServiceToken</code></a>&lt;<code>T</code>&gt;</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>T</code></p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>KernelError when no module has provided the token.</p><hr><h3 id="register" tabindex="-1">register() <a class="header-anchor" href="#register" aria-label="Permalink to “register()”">​</a></h3><blockquote><p><strong>register</strong>&lt;<code>Config</code>&gt;(<code>module</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L78" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:78</a></p><p>Adds a module. Legal only before <code>registerAll()</code> (or the first <code>start()</code>, which runs it).</p><h4 id="type-parameters-2" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-2" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to “Config”">​</a></h5><p><code>Config</code></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="module" tabindex="-1">module <a class="header-anchor" href="#module" aria-label="Permalink to “module”">​</a></h5><p><a href="./../#module"><code>Module</code></a>&lt;<code>Config</code>, <code>Events</code>&gt;</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>KernelError after <code>registerAll()</code> or when a module with the same id is already registered.</p><hr><h3 id="registerall" tabindex="-1">registerAll() <a class="header-anchor" href="#registerall" aria-label="Permalink to “registerAll()”">​</a></h3><blockquote><p><strong>registerAll</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L102" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:102</a></p><p>Runs all <code>register()</code> phases, validates providers and the dependency graph, and computes the start order. After it resolves, <code>get()</code> resolves every provided service even though <code>start()</code> has not run. Runs at most once per kernel; later calls are no-ops.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="throws-2" tabindex="-1">Throws <a class="header-anchor" href="#throws-2" aria-label="Permalink to “Throws”">​</a></h4><p>KernelError when a declared dependency has no provider or the dependency graph has a cycle.</p><hr><h3 id="start" tabindex="-1">start() <a class="header-anchor" href="#start" aria-label="Permalink to “start()”">​</a></h3><blockquote><p><strong>start</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L126" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:126</a></p><p>Runs <code>registerAll()</code> when it has not run, then runs <code>start()</code> phases in dependency order. Legal again after <code>stop()</code>: the <code>register()</code> phases do not rerun, so the modules&#39; services carry over into the next start.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="throws-3" tabindex="-1">Throws <a class="header-anchor" href="#throws-3" aria-label="Permalink to “Throws”">​</a></h4><p>KernelError when the kernel is already starting or started, when a declared dependency has no provider, or when the dependency graph has a cycle.</p><hr><h3 id="stop" tabindex="-1">stop() <a class="header-anchor" href="#stop" aria-label="Permalink to “stop()”">​</a></h3><blockquote><p><strong>stop</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/8d65b2be3b07f2172ff64e6ebf3b639ea8511a20/packages/kernel/src/kernel.ts#L144" target="_blank" rel="noreferrer">packages/kernel/src/kernel.ts:144</a></p><p>Runs <code>stop()</code> phases in reverse start order and detaches each module&#39;s event listeners. Failures are logged, not thrown, so one module cannot block the others&#39; teardown. Leaves the kernel registered, so <code>start()</code> may run it again; a no-op unless the kernel is started.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p>`,80)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};